function normalizeQuestionType(type) {
  const t = String(type || '').toLowerCase().trim();
  if (t === 'behavioral') return 'behavioral';
  if (t === 'situational' || t === 'gap_probe') return 'situational';
  if (t === 'cultural') return 'cultural';
  return 'technical';
}

const intro = {
  session_id: sessionId,
  question_text: "Hello! I am your AI Interviewer today. Welcome to your interview. To start off, how are you doing today?",
  question_type: "cultural",
  order_index: 0,
  source: "hr_reviewed_intro"
};

const questions = reviewedQuestions
