// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Supabase getAll returns ONE item PER ROW.
// Use $items() to collect ALL rows from multi-row nodes.
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

const session = $node["Fetch Session1"]?.json || {};
const resume  = $node["Fetch Resume"]?.json    || {};
const jd      = $node["Fetch JD"]?.json        || {};

const questionRows   = ($items("Fetch Questions1") || []).map(i => i.json);
const answerRows     = ($items("Fetch Answers1")   || []).map(i => i.json);
const proctoringRows = ($items("Fetch Proctoring1") || []).map(i => i.json);

// Build question lookup
const questionMap = {};
questionRows.forEach(q => { questionMap[q.id] = q; });

// â”€â”€â”€ Build enriched answer list including live assessment notes â”€â”€â”€
// ai_live_note was computed in real-time during the interview.
// It contains depth_signal, authenticity_signal, insufficiency_reason,
// and a recruiter note per answer â€” critical signal for accurate scoring.
const answerList = answerRows.map(a => {
  const liveNote = a.ai_live_note || a.ai_assessment || null;
  const wordCount = (a.answer_text || '').trim().split(/\s+/).filter(Boolean).length;

  return {
    question:             questionMap[a.question_id]?.question_text || 'Unknown',
    answer:               a.answer_text || 'No answer provided',
    type:                 questionMap[a.question_id]?.question_type || 'technical',
    source:               questionMap[a.question_id]?.source || 'unknown',
    word_count:           wordCount,
    // Live assessment signals from real-time analysis during the interview
    depth_signal:         liveNote?.depth_signal        || null,   // 'deep' | 'surface' | 'empty'
    authenticity_signal:  liveNote?.authenticity_signal || null,   // 'genuine' | 'vague' | 'suspicious' | 'inconsistent'
    insufficiency_reason: liveNote?.insufficiency_reason || null,  // 'lacks_depth' | 'lacks_evidence' | 'vague' | 'irrelevant' | null
    follow_up_triggered:  liveNote?.follow_up_prompted  || false,  // true if answer was insufficient enough to trigger a follow-up
    requested_clarification: liveNote?.requested_clarification || false, // true if candidate asked for clarification instead of answering
    recruiter_note:       liveNote?.note                || null,   // internal recruiter note from live analysis
    red_flags:            liveNote?.red_flags           || []
  };
});

// â”€â”€â”€ Aggregate live signals for calibration context â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const technicalAnswers  = answerList.filter(a => a.type === 'technical' && a.source !== 'llm_ts_dynamic_intro' && a.source !== 'hr_reviewed_intro');
const primaryAnswers    = answerList.filter(a => a.source !== 'llm_ts_followup' && a.source !== 'llm_ts_dynamic_intro' && a.source !== 'hr_reviewed_intro');

const depthCounts = { deep: 0, surface: 0, empty: 0, unknown: 0 };
const authCounts  = { genuine: 0, vague: 0, suspicious: 0, inconsistent: 0, unknown: 0 };
let followUpTriggeredCount    = 0;
let clarificationRequestCount = 0;
let insufficientTechnicalCount = 0;

answerList.forEach(a => {
  const d = a.depth_signal || 'unknown';
  depthCounts[d] = (depthCounts[d] || 0) + 1;
  const auth = a.authenticity_signal || 'unknown';
  authCounts[auth] = (authCounts[auth] || 0) + 1;
  if (a.follow_up_triggered) followUpTriggeredCount++;
  if (a.requested_clarification) clarificationRequestCount++;
  if (a.type === 'technical' && (a.depth_signal === 'empty' || a.insufficiency_reason)) insufficientTechnicalCount++;
});

const totalAnswered = answerList.length;
const emptyRatio    = totalAnswered > 0 ? depthCounts.empty / totalAnswered : 0;
const techEmptyRatio = technicalAnswers.length > 0 ? insufficientTechnicalCount / technicalAnswers.length : 0;

const signalSummary = {
  total_answers:            totalAnswered,
  depth_distribution:       depthCounts,
  authenticity_distribution: authCounts,
  follow_up_triggered_count: followUpTriggeredCount,
  clarification_request_count: clarificationRequestCount,
  insufficient_technical_count: insufficientTechnicalCount,
  empty_answer_ratio:       Math.round(emptyRatio * 100) + '%',
  tech_insufficient_ratio:  Math.round(techEmptyRatio * 100) + '%'
};

// â”€â”€â”€ Build structured proctoring summary â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const criticalEvents = proctoringRows.filter(e => e.severity === 'critical');
const warningEvents  = proctoringRows.filter(e => e.severity === 'warning');

const countByType = {};
proctoringRows.forEach(e => {
  countByType[e.event_type] = (countByType[e.event_type] || 0) + 1;
});

let proctoringRisk = 'low';
if (criticalEvents.length >= 5 || proctoringRows.length >= 20) proctoringRisk = 'high';
else if (criticalEvents.length >= 2 || warningEvents.length >= 5) proctoringRisk = 'medium';

const notableEvents = [
  ...criticalEvents,
  ...warningEvents
].slice(0, 10).map(e => ({
  type:      e.event_type,
  severity:  e.severity,
  timestamp: e.timestamp
}));

const proctoringSummary = {
  total_events:   proctoringRows.length,
  critical_count: criticalEvents.length,
  warning_count:  warningEvents.length,
  risk_level:     proctoringRisk,
  by_type:        countByType,
  notable_events: notableEvents
};

const truncate = (t, max) => !t ? '' : t.length > max ? t.slice(0, max) + '...[truncated]' : t;

const prompt = `You are a senior technical recruiter writing a post-interview evaluation. Your job is to score the candidate ACCURATELY and STRICTLY â€” based only on what they actually demonstrated in the live interview, not on what their resume claims.

