const content = JSON.parse($json.choices[0].message.content);
const compileData = $node["Compile Data"] ? $node["Compile Data"].json : ($node["Build Prompt"] ? $node["Build Prompt"].json : {});
const answers = compileData.answers || [];

// Identify "I don't know" and non-answer responses
const isRefusal = (ans) => {
  const clean = (ans || '').toLowerCase().trim();
  return (
    clean.length === 0 ||
    clean === 'no answer recorded' ||
    clean.includes("i don't know") ||
    clean.includes("dont know") ||
    clean.includes("do not know") ||
    clean.includes("read upon this") ||
    clean.includes("have to read") ||
    clean.includes("not sure") ||
    clean.includes("no idea")
  );
};

const refusalCount = answers.filter(a => isRefusal(a.answer)).length;
const totalAnswers = Math.max(1, answers.length);
const refusalRate = refusalCount / totalAnswers;

let technical_score = content.technical_score ?? 0;
let communication_score = content.communication_score ?? 0;
let problem_solving_score = content.problem_solving_score ?? 0;
let cultural_fit_score = content.cultural_fit_score ?? 0;
let overall_score = content.overall_score ?? 0;
let authenticity_score = content.authenticity_score ?? 0;
let recommendation = content.recommendation || 'consider';

// Enforce refusal score caps (clamping scores if refusal rate >= 30%)
if (refusalRate >= 0.5) {
  technical_score = Math.min(technical_score, 15);
  problem_solving_score = Math.min(problem_solving_score, 15);
  overall_score = Math.min(overall_score, 15);
  recommendation = 'no_go';
} else if (refusalRate >= 0.3) {
  technical_score = Math.min(technical_score, 30);
  problem_solving_score = Math.min(problem_solving_score, 30);
  overall_score = Math.min(overall_score, 30);
  recommendation = 'no_go';
}

return [{
  json: {
    session_id: compileData.session_id,
    technical_score,
    communication_score,
    problem_solving_score,
    cultural_fit_score,
    overall_score,
    authenticity_score,
    red_flag_count: content.red_flag_count ?? 0,
    red_flags: content.red_flags || [],
    resume_vs_reality: content.resume_vs_reality || [],
    strengths: content.strengths || [],
    weaknesses: content.weaknesses || [],
    recommendation,
    ai_rationale: content.ai_rationale || '',
    detailed_rationale: content.detailed_rationale || '',
    scoring_model_version: 'gpt-4.1-mini-v1',
    evaluated_at: new Date().toISOString()
  }
}];

